using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "reports");

    /// <summary>
    /// Creates a reporting configuration wired for telemetry and quality evaluation.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(
        IChatClient chatClient,
        string scenarioName)
    {
        // Quality evaluators – skip safety per requirements
        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var storage = new DiskBasedReportingStorage(StoragePath);

        return new ReportingConfiguration(
            storage,
            chatClient,
            evaluators,
            scenarioName: scenarioName,
            // Telemetry: capture token usage and latency in reports
            enableResponseCaching: false);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that token usage and latency metrics are captured.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static ReportingConfiguration? s_config;
    private static IChatClient? s_chatClient;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_chatClient = CreateChatClient();
        s_config = EvalConfig.CreateReportingConfig(s_chatClient, scenarioName: "Telemetry");
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_config is not null)
            await s_config.GenerateReportAsync();
    }

    [TestMethod]
    public async Task Response_captures_token_usage()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("token-usage");

        var response = await scenario.ChatClient!.GetResponseAsync("What is 2+2?");
        scenario.Record(response);

        Assert.IsNotNull(response.Usage, "Token usage should be reported.");
    }

    [TestMethod]
    public async Task Response_captures_latency()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("latency");

        var start = DateTime.UtcNow;
        var response = await scenario.ChatClient!.GetResponseAsync("Say hello.");
        scenario.Record(response);
        var elapsed = DateTime.UtcNow - start;

        Assert.IsTrue(elapsed.TotalMilliseconds > 0, "Latency should be measurable.");
    }

    private static IChatClient CreateChatClient()
    {
        // Uses Azure OpenAI via environment/config (same endpoint as AppHost)
        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                    ?? "https://localhost"),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "test"))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: runs relevance, coherence, fluency, and groundedness evaluators.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;
    private static IChatClient? s_chatClient;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_chatClient = CreateChatClient();
        s_config = EvalConfig.CreateReportingConfig(s_chatClient, scenarioName: "Quality");
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_config is not null)
            await s_config.GenerateReportAsync();
    }

    [TestMethod]
    public async Task Coach_response_meets_quality_thresholds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync("coach-quality");

        var messages = new[]
        {
            new ChatMessage(ChatRole.System, "You are a helpful coach."),
            new ChatMessage(ChatRole.User, "How can I improve my productivity?"),
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);

        // Evaluate quality
        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext:
            [
                new EvaluationContext("grounding",
                    "Productivity can be improved with time management, " +
                    "prioritization, breaks, and focused work sessions.")
            ]);

        // Assert quality scores meet minimum thresholds
        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result.Value is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"{result.Key} score {numeric.Value} is below threshold (3).");
            }
        }
    }

    private static IChatClient CreateChatClient()
    {
        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                    ?? "https://localhost"),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "test"))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
