using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and
/// compares quality scores side by side in the generated report.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "reports");

    [TestMethod]
    public async Task Compare_model_variants()
    {
        var prompt = new[]
        {
            new ChatMessage(ChatRole.System, "You are a helpful coach."),
            new ChatMessage(ChatRole.User, "Give me a short morning routine."),
        };

        var context = new EvaluationContext(
            "grounding",
            "A good morning routine includes hydration, exercise, and planning.");

        // --- Variant A ---
        var clientA = CreateChatClient("gpt-4o-mini");
        var configA = EvalConfig.CreateReportingConfig(clientA, scenarioName: "Compare-A");
        await using (var scenarioA = await configA.CreateScenarioRunAsync("morning-routine"))
        {
            var responseA = await scenarioA.ChatClient!.GetResponseAsync(prompt);
            await scenarioA.EvaluateAsync(prompt, responseA, additionalContext: [context]);
        }
        await configA.GenerateReportAsync();

        // --- Variant B ---
        var clientB = CreateChatClient("gpt-4o");
        var configB = EvalConfig.CreateReportingConfig(clientB, scenarioName: "Compare-B");
        await using (var scenarioB = await configB.CreateScenarioRunAsync("morning-routine"))
        {
            var responseB = await scenarioB.ChatClient!.GetResponseAsync(prompt);
            await scenarioB.EvaluateAsync(prompt, responseB, additionalContext: [context]);
        }
        await configB.GenerateReportAsync();

        // Both reports are stored under the same StoragePath.
        // Use `dotnet msai-eval report` to view the comparison dashboard.
        Assert.IsTrue(Directory.Exists(StoragePath), "Reports should be persisted for comparison.");
    }

    private static IChatClient CreateChatClient(string deployment)
    {
        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                    ?? "https://localhost"),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "test"))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

